"""World model for tu93 — a node/edge maze walked one node per action.

Layout, re-derived from the entry frame of each level (it moves between them):
  the non-background (5) pixels above row 63 form the maze bounding box, an
  odd x odd grid of 3px "coarse" cells.  (even,even) cells are nodes, cells
  with exactly one odd index are edges (2 = passable, 5 = wall).
  Node values: 0 plain, 14 goal.  Actors sit on nodes: 9 player, 8 ambusher,
  12 walker, each drawn as a filled block plus one marker pixel on the side it
  faces.

Actors:
  walker    steps one node along its facing on every player move and reverses
            when the corridor runs out.  Walkers pass through each other, so
            two of them can share a node and the frame then shows only one --
            which is why this model tracks actors in state instead of reading
            them back out of the grid.
  ambusher  stands still until the player steps into the single node it faces,
            then lunges onto it and kills the player.
  Stepping onto either actor from any other side destroys it.

Row 63 is a 64px bar filling from the right: zeros = round(64*moves/BUDGET),
with a per-level BUDGET.
"""

CELL = 3
BG = 5

DIRS = {1: (-1, 0), 2: (1, 0), 3: (0, -1), 4: (0, 1)}   # up, down, left, right
MARK = {1: (0, 1), 2: (2, 1), 3: (1, 0), 4: (1, 2)}     # marker pixel per facing
FACE = {v: k for k, v in MARK.items()}
OPPOSITE = {1: 2, 2: 1, 3: 4, 4: 3}
AXIS = {1: 0, 2: 0, 3: 1, 4: 1}          # vertical / horizontal
NODES = (0, 14)
ACTORS = (8, 12, 13)   # ambusher, walker, unknown 13 (treated as an ambusher)

# The bar is a per-level move allowance; solve new ones with run/budget.py.
BUDGETS = {0: 50, 1: 50, 2: 35, 3: 20, 4: 50, 5: 60, 6: 30, 7: 50, 8: 50}
DEFAULT_BUDGET = 50

LEVEL_ENTRY = {
    0:
        '',
    1:
        '',
    2:
        '',
    3:
        '',
    4:
        '',
    5:
        '',
    6:
        '',
    7:
        '',
    8:
        '',
}

ENTRY_GRIDS = {
    (15, 15, 11, 11, 8, 10, 22):
        '',
    (21, 12, 5, 13, 2, 12, 12):
        '',
    (18, 12, 9, 13, 8, 2, 33):
        '',
    (16, 21, 9, 9, 2, 2, 51):
        '',
    (14, 9, 11, 15, 6, 8, 37):
        '',
    (12, 12, 13, 13, 2, 2, 31):
        '',
    (18, 12, 9, 13, 2, 12, 28):
        '',
    (14, 14, 11, 11, 0, 6, 28):
        '',
}


def _unpack(s):
    return [[int(s[r * 64 + c], 16) for c in range(64)] for r in range(64)]


def _budget():
    try:
        lvl = CURRENT_LEVEL          # injected by the harness
    except NameError:
        lvl = 0
    return BUDGETS.get(lvl, DEFAULT_BUDGET)


def _zeros(grid):
    return sum(1 for v in grid[63] if v != 6)


def _bounds(grid):
    rs = [r for r in range(63) for c in range(64) if grid[r][c] != BG]
    cs = [c for r in range(63) for c in range(64) if grid[r][c] != BG]
    r0, c0 = min(rs), min(cs)
    return r0, c0, (max(rs) - r0 + 1) // CELL, (max(cs) - c0 + 1) // CELL


def _entry_key(grid):
    r0, c0, nr, nc = _bounds(grid)
    pi = pj = 0
    for i in range(nr):
        for j in range(nc):
            if grid[r0 + i * CELL + 1][c0 + j * CELL + 1] == 9:
                pi, pj = i, j
    return (r0, c0, nr, nc, pi, pj, _zeros(grid))


def _parse(grid):
    r0, c0, nr, nc = _bounds(grid)
    entry_grid = grid
    maze, player, actors = [], None, []
    for i in range(nr):
        row = []
        for j in range(nc):
            v = entry_grid[r0 + i * CELL + 1][c0 + j * CELL + 1]
            if v == 9 or v in ACTORS:
                mark, col = None, None
                for a in range(CELL):
                    for b in range(CELL):
                        px = entry_grid[r0 + i * CELL + a][c0 + j * CELL + b]
                        if px != v:
                            mark, col = (a, b), px
                if v == 9:
                    player = [i, j, FACE[mark]]
                else:
                    actors.append([v, i, j, FACE[mark], col, None])
                v = 0
            row.append(v)
        maze.append(row)
    # Actors can share a node, and the frame then shows only the one drawn
    # last: walkers cover ambushers, and among walkers the row-ascending /
    # column-descending one wins.  Both observed stacks match this order.
    actors.sort(key=lambda a: (a[1], -a[2]))
    b = _budget()
    return {'r0': r0, 'c0': c0, 'nr': nr, 'nc': nc, 'maze': maze,
            'player': player, 'actors': actors,
            'moves': (b * _zeros(entry_grid) + 32) // 64, 'dead': False,
            'trail': [tuple(player[:2])] if player else []}


def _walk(st):
    """Advance every walker one step; returns the nodes they landed on."""
    landed = []
    for a in st['actors']:
        if a[0] != 12:
            continue
        wdir = a[3]
        wdi, wdj = DIRS[wdir]
        ahead = _open(st, a[1], a[2], wdi, wdj)
        if ahead is None:
            a[3] = OPPOSITE[a[3]]                    # cornered: turn around
            continue
        a[1], a[2] = ahead
        if _open(st, a[1], a[2], wdi, wdj) is None:
            a[3] = OPPOSITE[a[3]]
        landed.append((a[1], a[2]))
    return landed


def _dists(st, node):
    """Node-graph distances from `node` (maze topology only)."""
    d = {node: 0}
    frontier = [node]
    while frontier:
        nxt = []
        for i, j in frontier:
            for act in (1, 2, 3, 4):
                step_to = _open(st, i, j, *DIRS[act])
                if step_to is not None and step_to not in d:
                    d[step_to] = d[(i, j)] + 1
                    nxt.append(step_to)
        frontier = nxt
    return d


def _dir_between(st, frm, to):
    for act in (1, 2, 3, 4):
        if _open(st, frm[0], frm[1], *DIRS[act]) == to:
            return act
    return None


def _toward(st, i, j, d):
    """A shortest-path step from (i,j) into the distance map `d`."""
    best = None
    for act in (1, 2, 3, 4):
        step_to = _open(st, i, j, *DIRS[act])
        if step_to is None or step_to not in d:
            continue
        if best is None or d[step_to] < d[best[1]]:
            best = (act, step_to)
    return best


def init_state(entry_grid):
    """Rebuild the world from the level's opening frame, not the frame given.

    Two walkers can share a node, and the frame then shows only one of them, so
    a state parsed straight out of the current frame silently loses walkers.
    Walker motion does not depend on the player, so replaying them from the
    level entry for `moves` steps recovers the hidden ones; the observed frame
    is then only used for the player, the ambushers and for spotting walkers
    the player has destroyed.
    """
    obs = _parse(entry_grid)
    try:
        lvl = CURRENT_LEVEL
    except NameError:
        lvl = 0
    base = LEVEL_ENTRY.get(lvl)
    if base is None:
        return obs
    st = _parse(_unpack(base))
    st['moves'] = obs['moves']
    st['player'] = obs['player']
    # An actor can be hidden under another, so a node showing an ambusher may
    # also hold a walker.  Collect both, and score candidate phases against them.
    walk_seen, occupied = set(), set()
    for i in range(st['nr']):
        for j in range(st['nc']):
            v = entry_grid[st['r0'] + i * CELL + 1][st['c0'] + j * CELL + 1]
            if v == 12:
                walk_seen.add((i, j))
            if v in ACTORS:
                occupied.add((i, j))

    # Walkers advance once per *successful* player move, while the bar counts
    # blocked ones too, so the move count is only an upper bound on their step
    # count.  Pick the step count whose walker positions actually match the
    # frame, preferring the one that implies the fewest destroyed walkers.
    best, best_actors = None, st['actors']
    for s in range(st['moves'] + 1):
        if s:
            _walk(st)
        here = set((a[1], a[2]) for a in st['actors'] if a[0] == 12)
        score = (len(here - occupied) + len(walk_seen - here), -s)
        if best is None or score < best:
            best, best_actors = score, [a[:] for a in st['actors']]
    # Walkers come from the replay (they can be hidden), static ambushers from
    # the replay too, but a woken type-13 hunter's course depends on where the
    # player has been, so read it straight off the frame.
    st['actors'] = [a for a in best_actors
                    if a[0] != 13 and (a[1], a[2]) in occupied]
    st['actors'] += [a for a in obs['actors'] if a[0] == 13]
    return st


def _open(st, i, j, di, dj):
    """The node two coarse cells along (di,dj), if there is an edge and a node."""
    ti, tj = i + 2 * di, j + 2 * dj
    if not (0 <= ti < st['nr'] and 0 <= tj < st['nc']):
        return None
    if st['maze'][i + di][j + dj] != 2 or st['maze'][ti][tj] not in NODES:
        return None
    return ti, tj


def _paint(g, st, i, j, fill, mark=None, col=4):
    for a in range(CELL):
        for b in range(CELL):
            g[st['r0'] + i * CELL + a][st['c0'] + j * CELL + b] = fill
    if mark is not None:
        g[st['r0'] + i * CELL + mark[0]][st['c0'] + j * CELL + mark[1]] = col


def _render(st):
    g = [[BG] * 64 for _ in range(63)] + [[6] * 64]
    for i in range(st['nr']):
        for j in range(st['nc']):
            v = st['maze'][i][j]
            if v != BG:
                _paint(g, st, i, j, v)
    # Actors can share a node -- a walker passes straight over an ambusher --
    # and only one gets drawn.  The walker covers the ambusher unless the two
    # face along the same axis, in which case the ambusher stays on top; among
    # stacked walkers the last in list order wins.
    top = {}
    for a in st['actors']:
        node = (a[1], a[2])
        cur = top.get(node)
        if cur is None:
            top[node] = a
            continue
        if a[0] == 12 and cur[0] != 12 and AXIS[cur[3]] == AXIS[a[3]]:
            continue
        if a[0] != 12 and cur[0] == 12 and AXIS[a[3]] == AXIS[cur[3]]:
            top[node] = a
            continue
        if a[0] == 12 or cur[0] != 12:
            top[node] = a
    for a in top.values():
        _paint(g, st, a[1], a[2], a[0], MARK[a[3]], a[4])
    if st['player'] is not None:
        pi, pj, pf = st['player']
        _paint(g, st, pi, pj, 9, MARK[pf], 4)
    b = _budget()
    nz = (128 * st['moves'] + b) // (2 * b)          # round(64*moves/b)
    for c in range(63, 63 - nz, -1):
        g[63][c] = 0
    return g


def predict(state, grid, action, x=None, y=None):
    st = {k: v for k, v in state.items()}
    st['maze'] = [row[:] for row in state['maze']]
    st['trail'] = list(state.get('trail') or [])
    st['actors'] = [a[:] for a in state['actors']]
    st['player'] = list(state['player']) if state['player'] else None
    info = {}
    if action not in DIRS or st['player'] is None:
        return _render(st), info, st

    pi, pj, _ = st['player']
    di, dj = DIRS[action]
    dest = _open(st, pi, pj, di, dj)
    if dest is None:
        # A blocked move still burns a move, but nothing else happens: the
        # walkers do NOT advance, so bumping a wall is not a usable "wait".
        st['moves'] += 1
        return _render(st), info, st
    ni, nj = dest
    st['moves'] += 1
    st['player'] = [ni, nj, action]
    st['trail'] = list(state.get('trail') or []) + [(ni, nj)]
    # Stepping onto an actor destroys it -- but a walker that stepped onto an
    # ambusher facing the same way left it standing, so approaching an actor
    # from directly behind evidently does not kill it.  Treat that as fatal
    # rather than find out the expensive way.
    if any((a[1], a[2]) == (ni, nj) and a[3] == action for a in st['actors']):
        st['player'] = None
        info['dead'] = True
        return _render(st), info, st
    st['actors'] = [a for a in st['actors'] if (a[1], a[2]) != (ni, nj)]

    if (ni, nj) in _walk(st):
        st['player'] = None
        info['dead'] = True
        return _render(st), info, st

    for a in st['actors']:
        if a[0] == 12:
            continue
        adi, adj = DIRS[a[3]]
        if _open(st, a[1], a[2], adi, adj) == (ni, nj):
            a[1], a[2] = ni, nj
            a[4] = max(a[4] - 4, 3)
            st['player'] = None
            info['dead'] = True
            return _render(st), info, st

    # A type-13 hunter sits dormant (marker 15) until the player steps anywhere
    # along the line it faces; that turn it only wakes (marker 11).  After that
    # it chases, moving one node along a shortest path to the player each turn
    # and re-aiming its marker at the player, and kills on contact.
    dist = _dists(st, (ni, nj))
    for a in st['actors']:
        if a[0] != 13:
            continue
        if a[4] == 15:
            ri, rj = a[1], a[2]
            while True:
                nxt = _open(st, ri, rj, *DIRS[a[3]])
                if nxt is None:
                    break
                ri, rj = nxt
                if (ri, rj) == (ni, nj):
                    a[4] = 11
                    break
            continue
        # The hunter chases the player's WAKE, not the player: it heads for
        # where the player stood two moves ago, and once it gets there it just
        # walks the player's route at that fixed lag.
        trail = st['trail']
        lag = a[5] or 2
        if len(trail) <= lag:
            continue
        target, aim_to = trail[-1 - lag], trail[-lag]
        if a[5] is not None:
            step_to = target
        else:
            move = _toward(st, a[1], a[2], _dists(st, target))
            if move is None:
                continue
            step_to = move[1]
            if step_to != target:
                aim_to = None
        act = _dir_between(st, (a[1], a[2]), step_to)
        if act is None:
            continue
        a[1], a[2] = step_to
        if a[5] is None and step_to == target:
            a[5] = lag                               # caught the player's wake
        if (a[1], a[2]) == (ni, nj):
            st['player'] = None
            info['dead'] = True
            return _render(st), info, st
        aim = (_dir_between(st, step_to, aim_to) if aim_to
               else (_toward(st, a[1], a[2], _dists(st, target)) or [None])[0])
        if aim is not None:
            a[3] = aim

    if st['maze'][ni][nj] == 14:
        info['level_up'] = True
        nxt = ENTRY_GRIDS.get(_entry_key(grid))
        if nxt is not None:
            return _unpack(nxt), info, st
    return _render(st), info, st
